//! Session hub — consolidates skill context, verify-all trust entry, lock, config access.
use anyhow::Result;
use crate::config::Config;

pub mod change_detection;
pub mod lock;
pub mod skill_interface;

/// Acquire session lock, run verify-all, release. Hub owns the trust entrypoint.
pub fn verify_all(cfg: &Config) -> Result<()> {
    let _guard = lock::acquire(&cfg.residual_dir)?;
    crate::verify::run(cfg, crate::cli::VerifyCheck::All)?;
    // lock released via Drop
    Ok(())
}

/// Skill-data / context loading entry used by CLI.
pub fn skill_data(cfg: &Config, name: &str) -> Result<()> {
    skill_interface::data(cfg, name)
}

/// Config access used by session flows (thin wrapper).
pub fn load_config() -> Result<Config> {
    crate::config::load()
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::tempdir;

    #[test]
    fn session_hub_acquires_lockfile() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();

        let guard = lock::acquire(&residual).expect("acquire should succeed");
        let lock_path = residual.join(".session.lock");
        assert!(lock_path.exists(), "lockfile should exist while held");
        drop(guard);
        // After release, lock may be removed or marked released
        assert!(
            !lock_path.exists() || lock::is_released(&residual),
            "lock should be released after drop"
        );
    }

    #[test]
    fn session_hub_lock_respects_ttl() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();

        // Write an expired lock manually
        lock::write_stale_for_test(&residual, std::time::Duration::from_secs(0)).unwrap();
        // Acquire should succeed by reclaiming expired lock
        let _guard = lock::acquire_with_ttl(&residual, std::time::Duration::from_secs(60))
            .expect("should reclaim expired lock");
        assert!(residual.join(".session.lock").exists());
    }

    #[test]
    fn session_hub_change_detection_hashes_managed_files() {
        let dir = tempdir().unwrap();
        let residual = dir.path().join("residual");
        std::fs::create_dir_all(&residual).unwrap();
        std::fs::write(residual.join("stressors.csv"), "id,description\n").unwrap();
        std::fs::write(residual.join("purposes.csv"), "id,description\n").unwrap();

        let snap1 = change_detection::snapshot(&residual).expect("snapshot");
        assert!(!snap1.is_empty(), "snapshot should include managed files");

        std::fs::write(residual.join("stressors.csv"), "id,description\nS-01,x\n").unwrap();
        let snap2 = change_detection::snapshot(&residual).expect("snapshot");
        assert_ne!(snap1, snap2, "hash should change after write");
    }
}

//! Minimal session lockfile under residual/ — acquire / release / ttl.
use anyhow::{bail, Context, Result};
use std::fs;
use std::path::{Path, PathBuf};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

const LOCK_FILE: &str = ".session.lock";
const DEFAULT_TTL: Duration = Duration::from_secs(300);

pub struct LockGuard {
    path: PathBuf,
}

impl Drop for LockGuard {
    fn drop(&mut self) {
        let _ = fs::remove_file(&self.path);
    }
}

pub fn lock_path(residual_dir: &Path) -> PathBuf {
    residual_dir.join(LOCK_FILE)
}

pub fn acquire(residual_dir: &Path) -> Result<LockGuard> {
    acquire_with_ttl(residual_dir, DEFAULT_TTL)
}

pub fn acquire_with_ttl(residual_dir: &Path, ttl: Duration) -> Result<LockGuard> {
    let path = lock_path(residual_dir);
    if path.exists() {
        if is_expired(residual_dir, ttl)? {
            let _ = fs::remove_file(&path);
        } else {
            bail!("session lock held: {}", path.display());
        }
    }
    let now = now_secs();
    let expires = now + ttl.as_secs();
    fs::write(&path, format!("pid={}\nacquired={}\nexpires={}\n", std::process::id(), now, expires))
        .with_context(|| format!("write lock {}", path.display()))?;
    Ok(LockGuard { path })
}

pub fn release(residual_dir: &Path) -> Result<()> {
    let path = lock_path(residual_dir);
    if path.exists() {
        fs::remove_file(&path).with_context(|| format!("remove lock {}", path.display()))?;
    }
    Ok(())
}

pub fn is_released(residual_dir: &Path) -> bool {
    !lock_path(residual_dir).exists()
}

fn is_expired(residual_dir: &Path, _default_ttl: Duration) -> Result<bool> {
    let path = lock_path(residual_dir);
    let content = fs::read_to_string(&path)?;
    for line in content.lines() {
        if let Some(rest) = line.strip_prefix("expires=") {
            let expires: u64 = rest.trim().parse().unwrap_or(0);
            return Ok(now_secs() >= expires);
        }
    }
    // No expires field → treat as expired
    Ok(true)
}

fn now_secs() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0)
}

/// Test helper: write a lock that is already expired (ttl=0 means expires immediately).
#[cfg(any(test, doctest))]
pub fn write_stale_for_test(residual_dir: &Path, _ttl: Duration) -> Result<()> {
    let path = lock_path(residual_dir);
    let past = now_secs().saturating_sub(10);
    fs::write(&path, format!("pid=0\nacquired={}\nexpires={}\n", past, past))?;
    Ok(())
}

