//! Components registry — loads residual/components.csv for architecture sets.
use anyhow::{Context, Result};
use serde::{Deserialize, Serialize};
use std::path::Path;

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct Component {
    pub name: String,
    pub description: String,
    pub status: String,
    pub architecture_set: String,
}

pub fn load(residual_dir: &Path) -> Result<Vec<Component>> {
    let path = residual_dir.join("components.csv");
    if !path.exists() {
        return Ok(vec![]);
    }
    let mut rdr = csv::ReaderBuilder::new()
        .has_headers(true)
        .from_path(&path)
        .with_context(|| format!("read {}", path.display()))?;
    let mut result = Vec::new();
    for record in rdr.deserialize() {
        let c: Component = record?;
        result.push(c);
    }
    Ok(result)
}

pub fn for_architecture(residual_dir: &Path, set: &str) -> Result<Vec<Component>> {
    Ok(load(residual_dir)?
        .into_iter()
        .filter(|c| c.architecture_set == set)
        .collect())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::path::PathBuf;

    #[test]
    fn components_csv_loads_A_C1_set() {
        // Prefer repo residual/ when present (integration-style), else fixture.
        let candidates = [
            PathBuf::from("residual"),
            PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("residual"),
        ];
        let residual = candidates
            .into_iter()
            .find(|p| p.join("components.csv").exists())
            .expect("components.csv must exist under residual/");

        let set = for_architecture(&residual, "A-C1").expect("load A-C1");
        assert!(
            !set.is_empty(),
            "A-C1 architecture set must be non-empty"
        );
        let names: Vec<&str> = set.iter().map(|c| c.name.as_str()).collect();
        for required in &[
            "skill-lifecycle",
            "session-hub",
            "evidence",
            "matrix-view",
            "lexicon",
            "change-detection",
            "components-registry",
        ] {
            assert!(
                names.contains(required),
                "missing component '{}' in A-C1 set: {:?}",
                required,
                names
            );
        }
        assert!(
            set.iter().all(|c| c.status == "proposed"),
            "all A-C1 components should be status=proposed"
        );
        assert!(
            set.iter().all(|c| c.architecture_set == "A-C1"),
            "all filtered rows should be A-C1"
        );
    }
}

