//! SHA/hash snapshot of managed residual files before write.
use anyhow::Result;
use std::collections::BTreeMap;
use std::path::Path;

/// Managed CSV / data files tracked for change detection.
pub const MANAGED_FILES: &[&str] = &[
    "stressors.csv",
    "purposes.csv",
    "attractors.csv",
    "terminology.csv",
    "components.csv",
];

pub type Snapshot = BTreeMap<String, String>;

/// Hash snapshot of managed files present under residual_dir.
pub fn snapshot(residual_dir: &Path) -> Result<Snapshot> {
    let mut map = BTreeMap::new();
    for name in MANAGED_FILES {
        let path = residual_dir.join(name);
        if path.is_file() {
            let data = std::fs::read(&path)?;
            map.insert((*name).to_string(), hash_bytes(&data));
        }
    }
    Ok(map)
}

pub fn hash_bytes(data: &[u8]) -> String {
    // Simple FNV-1a 64-bit hex for deterministic, dep-free hashing
    let mut hash: u64 = 0xcbf29ce484222325;
    for byte in data {
        hash ^= u64::from(*byte);
        hash = hash.wrapping_mul(0x100000001b3);
    }
    format!("{:016x}", hash)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn hash_bytes_stable() {
        assert_eq!(hash_bytes(b"hello"), hash_bytes(b"hello"));
        assert_ne!(hash_bytes(b"hello"), hash_bytes(b"world"));
    }
}

